/** Applies [WorldSpawnNpcs.stationary]. A type edit, so the boot config sync picks it up. */
internal object WorldSpawnNpcEditor : NpcEditor() {
    init {
        WorldSpawnNpcs.stationary.forEach { edit(it) { wanderRange = 0 } }
    }
}
